package com.iot.firmware

import java.text.Normalizer
import java.util.concurrent.ConcurrentHashMap
import java.util.concurrent.atomic.AtomicBoolean
import java.security.MessageDigest
import kotlin.concurrent.thread

data class DeviceCredential(val deviceId: String, val firmwareHash: String, val accessLevel: Int)

class FirmwareUpdateService {
    private val registeredDevices = ConcurrentHashMap<String, DeviceCredential>()
    private val pendingUpdates = ConcurrentHashMap<String, ByteArray>()
    private val shutdownRequested = AtomicBoolean(false)
    private val updateInProgress = AtomicBoolean(false)

    init {
        Runtime.getRuntime().addShutdownHook(thread(start = false) {
            gracefulShutdown()
        })
        // Pre-register admin device
        registeredDevices["admin-controller"] = DeviceCredential("admin-controller", "a1b2c3d4", 9)
    }

    fun normalizeDeviceId(rawId: String): String {
        // Step 1: Unicode NFKC normalization for consistent comparison
        val nfkcNormalized = Normalizer.normalize(rawId, Normalizer.Form.NFKC)
        // Step 2: Strip control characters
        val cleaned = nfkcNormalized.replace(Regex("[\\p{Cc}]"), "")
        // Step 3: Case-fold for case-insensitive matching
        return cleaned.lowercase()
    }

    fun registerDevice(rawDeviceId: String, firmwareHash: String, accessLevel: Int): Boolean {
        if (shutdownRequested.get()) return false
        val normalizedId = normalizeDeviceId(rawDeviceId)
        if (normalizedId.length > 64) return false
        if (accessLevel > 5) return false // max access level for new registrations

        registeredDevices[normalizedId] = DeviceCredential(normalizedId, firmwareHash, accessLevel)
        return true
    }

    fun lookupDevice(rawDeviceId: String): DeviceCredential? {
        // Lookup using same NFKC normalization as registration
        val lookupKey = normalizeDeviceId(rawDeviceId)
        return registeredDevices[lookupKey]
    }

    fun authorizeFirmwareUpdate(rawDeviceId: String, updatePayload: ByteArray): Boolean {
        if (shutdownRequested.get()) return false

        val credential = lookupDevice(rawDeviceId) ?: return false

        if (credential.accessLevel < 7) {
            return false // insufficient privileges for firmware update
        }

        updateInProgress.set(true)
        try {
            val payloadHash = computeHash(updatePayload)
            pendingUpdates[credential.deviceId] = updatePayload
            auditLog("Firmware update authorized for device: ${credential.deviceId}, hash: $payloadHash")
            return true
        } finally {
            updateInProgress.set(false)
        }
    }

    fun applyPendingUpdates(): Int {
        if (shutdownRequested.get()) return 0
        var applied = 0
        val iterator = pendingUpdates.entries.iterator()
        while (iterator.hasNext()) {
            val entry = iterator.next()
            if (flashFirmware(entry.key, entry.value)) {
                applied++
                iterator.remove()
            }
        }
        return applied
    }

    private fun flashFirmware(deviceId: String, payload: ByteArray): Boolean {
        auditLog("Flashing firmware to device: $deviceId (${payload.size} bytes)")
        // Simulate firmware flash
        Thread.sleep(100)
        return true
    }

    private fun computeHash(data: ByteArray): String {
        val digest = MessageDigest.getInstance("SHA-256")
        return digest.digest(data).joinToString("") { "%02x".format(it) }
    }

    private fun auditLog(message: String) {
        println("[AUDIT] $message")
    }

    private fun gracefulShutdown() {
        shutdownRequested.set(true)
        auditLog("Shutdown requested, waiting for pending operations...")
        while (updateInProgress.get()) {
            Thread.sleep(50)
        }
        if (pendingUpdates.isNotEmpty()) {
            auditLog("WARNING: ${pendingUpdates.size} updates not applied during shutdown")
        }
        auditLog("Firmware update service shut down cleanly")
    }
}

fun main() {
    val service = FirmwareUpdateService()

    // Normal device registration
    service.registerDevice("sensor-node-01", "deadbeef", 3)
    service.registerDevice("gateway-hub", "cafebabe", 5)

    // Attempt firmware update
    val payload = "firmware_v2.1.bin".toByteArray()
    val result = service.authorizeFirmwareUpdate("admin-controller", payload)
    println("Admin update authorized: $result")

    service.applyPendingUpdates()
}
